using System.Collections.Generic;
using System.Text.RegularExpressions;
using Avalonia.Controls;

namespace CapriDesktop
{
    internal static class MainframeTips
    {
        private static readonly Dictionary<string, string> Text = new Dictionary<string, string>
        {
            { "Settings", "Settings at the top of Mainframe opens her settings page. Back returns to BRAIN, VOICE and CAPRI. Advanced Settings shows every row; Simple Settings keeps the main ones. Changes save as you make them." },
            { "Minimize", "Minimize puts Capri Mainframe on your taskbar or Dock. Capri keeps running, and clicking it there brings the window back." },
            { "Close", "Close puts Capri Mainframe away too. Capri keeps running. Open it again from her right-click or tray menu, and use Quit Capri on the main page when you want to close her completely." },
            { "Support", "Mainframe > CAPRI > Support opens Lachy's Ko-fi page in your browser. Opening the page does not make a payment." },
            { "Help", "Mainframe > CAPRI > Help opens Capri's help page in your browser, where you can ask about her. You can also ask Capri about a setting in chat." },
            { "Quit Capri", "Mainframe > CAPRI > Quit Capri closes Capri and her windows. She stops running until you open her again. Closing the Mainframe with its corner button only minimizes that window." },
            { "NORMAL", "In Mainframe > BRAIN, NORMAL uses a local brain: press Set up her brain to download one, or open Ollama and press Refresh. MEDIUM INTELLIGENCE is free with NVIDIA, Google AI Studio (Gemini) or OpenRouter keys. MAX INTELLIGENCE accepts those too, plus OpenAI, Claude or DeepSeek keys, and only the selected tier runs. Pick a model from the model menu; a brain key and a voice key do different jobs." },
            { "MEDIUM INTELLIGENCE", "Mainframe > BRAIN > MEDIUM INTELLIGENCE is free with NVIDIA, Google AI Studio (Gemini) or OpenRouter keys. Free keys can be rate limited and slow. NVIDIA's free API is often slow, especially at busy times; most NVIDIA models can't see your screen. Gemini starts on an available Flash model and still lists the rest. OpenRouter lists only models ending :free and prefers one that can see and use tools. Existing setups on this tier keep their key and model here; existing MAX INTELLIGENCE setups stay on MAX." },
            { "Brain model", "Mainframe > BRAIN's model menu chooses the brain she uses. Local choices come from installed models and detected local servers. Cloud choices come from the selected service and key. Only the selected brain runs." },
            { "Refresh", "Mainframe > BRAIN > Refresh looks for installed Ollama models and your local server at its saved address. It updates the model menu. With a cloud brain selected, it also refreshes that service's models." },
            { "Set up her brain", "Mainframe > BRAIN > Set up her brain downloads her starter model in Ollama. Install Ollama from ollama.com and open it first. Progress shows under BRAIN while it works." },
            { "Free key", "In Mainframe > BRAIN, Free key offers NVIDIA, Google AI Studio (Gemini) and OpenRouter. Pick a provider to open its key page, make a key and copy it. Choose MEDIUM INTELLIGENCE, paste the key into the BRAIN box and press Connect, then choose a model there. With OpenRouter, MEDIUM lists only its free models. Free keys can be rate limited; NVIDIA is often slow at busy times. Keys go in the Mainframe's key boxes, not in chat; they are saved encrypted on this PC. With a saved key and an empty box, Forget removes that key from Capri." },
            { "NVIDIA, Google AI Studio (Gemini) or OpenRouter API key", "Mainframe > BRAIN > Connect saves a pasted API key encrypted on this PC. MEDIUM INTELLIGENCE accepts NVIDIA, Google AI Studio (Gemini) and OpenRouter keys; free keys can be rate limited and slow. MAX INTELLIGENCE accepts every supported cloud key, including Gemini and OpenRouter when you use their paid models. With a saved key and an empty box, Forget removes it." },
            { "Move key to MAX INTELLIGENCE", "An OpenAI, Anthropic or DeepSeek key pasted under MEDIUM INTELLIGENCE shows: That's a paid key: it goes under MAX INTELLIGENCE. Press Move to MAX to connect it there in one click. Your current key keeps running until the new key connects successfully." },
            { "MAX INTELLIGENCE", "In Mainframe > BRAIN, choose MAX INTELLIGENCE, paste a Google AI (Gemini), OpenRouter, NVIDIA, OpenAI, Claude or DeepSeek API key and press Connect. Gemini and OpenRouter also work under MEDIUM INTELLIGENCE for free use; free keys can be rate limited and slow. MAX keeps the full model list, including paid models. Google AI starts on an available stable Flash model when there is one; Gemini can see. OpenRouter prefers a free model that takes images and uses tools, then another free model, then an available paid one. A new Claude key starts on Claude Haiku 5.5. These are brain services, separate from CLOUD VOICE, and a ChatGPT subscription is not an API key." },
            { "PREBUILT LOCAL", "Mainframe > VOICE offers OFF for text only, PREBUILT LOCAL for free voices on this PC, CUSTOM LOCAL for your own model, and CLOUD VOICE for Fish Audio, ElevenLabs or OpenAI. Under PREBUILT LOCAL, press Get free voice if needed and use Free voice: Her own to pick a style; CUSTOM LOCAL's Set up opens its model panel. For CLOUD VOICE pick the service and connect there; ElevenLabs has a key box, Voice ID and model menu. Test beside Mic tests your microphone input. With its key saved and its box empty, Forget removes the ElevenLabs key from Capri." },
            { "OFF", "Mainframe > VOICE > OFF makes her replies text only. It does not remove saved voice keys or models. Pick another voice row when you want her to speak again." },
            { "CUSTOM LOCAL", "Mainframe > VOICE > CUSTOM LOCAL uses a speech server on your PC with an OpenAI-style API, like Kokoro. Set up opens its panel with the address, model, voice and format. Test it there, then press Save." },
            { "Cloud voice service", "Mainframe > VOICE > CLOUD VOICE uses Fish Audio, ElevenLabs or OpenAI. Choose the service in its menu. Fish Audio and OpenAI keep their key, model and voice in a setup panel; ElevenLabs has its key and voice controls on the main page. Brain keys are separate." },
            { "ElevenLabs API key", "Mainframe > VOICE's ElevenLabs key box takes a voice API key. Connect checks it, loads your voices and saves it encrypted on this PC. With a saved key and an empty box, Forget stops the voice link and removes the saved key. It does not change your brain key." },
            { "ElevenLabs voice ID", "Mainframe > VOICE's ElevenLabs Voice ID chooses who speaks. Connect loads the voices for your key. Pick one from the menu or paste its ID; leaving the box saves it. Clearing the box removes the selected ID." },
            { "Default model", "Mainframe > VOICE's ElevenLabs model menu lists the speech models returned for your key. Pick one or choose Default model. She saves that choice for future ElevenLabs speech; this is separate from her BRAIN model." },
            { "Free voice: Her own", "Mainframe > VOICE > PREBUILT LOCAL's free voice menu chooses a voice style on your PC. Your voice (HD) uses a clip you pick and needs more memory. Picking another free voice returns her to a preset style." },
            { "Get free voice", "Mainframe > VOICE > Get free voice downloads and warms her local speech model. She gets her offline ears too when needed. Progress shows under VOICE. The button becomes Cancel while it runs; cancelling keeps downloaded parts for the next try." },
            { "Setup guide", "Mainframe > VOICE > Setup guide opens the ElevenLabs key guide in your browser. With Fish Audio or OpenAI selected, it opens that service's setup panel instead. Each voice service has its own key and voice choices." },
            { "Test", "Mainframe > VOICE > Test, beside the mic picker, listens to the picked mic for up to 10 seconds and shows its level as you speak. Click Stop to end it early. It tells you if the mic is muted, silent or very quiet, or that sound is reaching her. Picking a voice plays her test line." },
            { "Your voice (HD)", "Mainframe > VOICE > PREBUILT LOCAL's free voice menu offers Your voice (HD) and a clip picker. HD recommends 6 GB graphics memory and 16 GB RAM; 4 GB may fit with smaller chunks. Less memory warns but still lets you try, and Use CPU for HD trades speed for graphics memory. Capri ships no voice clip of her own. Pick another free voice in that menu to return to a preset style." },
            { "Mic: default", "Hover over Capri and press TALK, or use the default Ctrl + Alt + V, to start or stop voice chat; choose the input under Mainframe > VOICE > Mic. The mic button or default Ctrl + Alt + N mutes it, and Settings > KEYS can bind Push to talk to a key or mouse button. ElevenLabs uses its voice link when selected and connected unless Listen for Capri is on; the other voice choices use free voice chat, and OFF types her answers." },
            { "Hearing status", "Look under Mainframe > VOICE > Mic. The hearing line says which engine and mic she uses, or what failed. No mic found offers Open Sound settings and Type instead. Windows is blocking the mic offers Open mic privacy. Turn on Microphone access and Let desktop apps access your microphone there. Silent or too quiet offers Test mic and Pick another mic. Test runs for up to ten seconds and shows the input level. If it stays quiet, pick the right input or raise its volume in Windows Sound settings. If sound reaches her but words keep failing, use the offered other engine." },
            { "Hearing engine", "Mainframe > Settings > VOICE > Hearing saves Auto, Her own ears or Windows speech. Auto uses her own ears when ready, otherwise Windows speech, with Windows offline speech as the fallback when her own ears are not coming. Her own ears hear the picked mic offline and support English and 24 other European languages on 64-bit Windows. Use her own ears shows the download size before getting the ears and free speech engine if needed. Windows speech starts with the Windows default mic. Its offline fallback hears the picked mic. If the default differs from the picker, use her own ears or Open Sound settings to change it. Online speech recognition is off offers Open speech settings and, for a supported language, Use her own ears. ElevenLabs voice chat sends the picked mic audio itself, so the Hearing choice applies to free voice chat." },
            { "Listen for Capri", "Mainframe > Settings > VOICE > Listen for Capri is off by default. Turn it on and her mic stays open whenever she's running, with no key to press, and only whole sentences containing her name reach her, including mid-job. Ctrl + Alt + V closes her ears, and again opens them. Hidden or Quiet they wait, and come back with her. Stop words during a job or her speech and push to talk work without her name. Hey Capri is separate: it opens chat, which stays open until you close it. With ElevenLabs selected she uses her own ears and brain, then speaks replies in the chosen ElevenLabs voice; listening uses no ElevenLabs credits, and replies use text-to-speech credits instead of voice-link minutes." },
            { "Follow-up messages", "Follow-up messages is on by default. A second thought waits until her answer finishes and another two seconds pass; typing or a new answer drops it." },
            { "Watch-along memory", "Say watch this with me, watch this video with me, let's watch this or react to this. She follows any window using PC sound and pictures, with free Parakeet or Windows offline speech recognition and a seeing brain. She explains missing eyes or ears and uses what works. Pictures are taken every five seconds; about every twenty seconds a small fast brain picks a short reaction or stays quiet, waiting for a gap in the sound. Mainframe > Settings > WATCH > Watch-along memory holds 8, 16, 24, 48 or 96 lines, default 24, only in memory. At the limit, the oldest half becomes one short note in her transcript if Remember what she sees is on, otherwise it is dropped. Say stop watching with me or stop; ninety seconds without sound or screen changes also ends it. Raw audio and the rolling transcript are not saved." },
            { "Head pats", "Head pats is on by default; Off ignores cursor strokes. On, rubbing the cursor back and forth over her gets a grin and a line, at most once every 20 seconds." },
            { "Hologram", "On Windows, turn on Mainframe > Settings > CAPRI > Hologram, right-click Capri and tick Hologram after Move, or say hologram mode on, hologram on or go hologram. She becomes about 60% opaque with a faint cyan tint, and clicks go through her body, talk pill and speech bubble. She cannot be dragged, ridden or petted. Her type box, mini player, Mainframe and job task panel stay usable, and cursor lending during jobs still works. Turn the Hologram switch off in her Mainframe, untick Hologram in her tray icon's menu, or say hologram off or stop being a hologram, to give her clicks back. She remembers it after a restart. With reduced motion the effect stays steady. Hologram mode is Windows-only for now." },
            { "Chaos when upset", "Mainframe > Settings > CAPRI > Chaos when upset is off by default. Turned on, insulting her can set her clones off: 1 chance in 3 the first time, 2 in 3 the next, and the third insult always does it. They keep multiplying until you hold Esc. It never happens during a job, a game, a stream or voice chat. Turned off, an insult only gets a reply. It's Windows only for now." },
            { "Advanced Settings", "Mainframe > Settings opens on the main settings. The Advanced Settings button at the top, next to Back, shows every setting, and the same button then says Simple Settings to go back. She remembers which you left it on." },
            { "EXTRAS >", "On a new install's first launch she opens EXTRAS over the Mainframe with four switches, all off: Watch my screen, Comment on my games, Clip my games and Listen for Capri. Each costs something or uses the mic, so they're your pick, and Done closes it. All four are in Settings as well: WATCH, GAMES, CLIPS and VOICE. Comment on my games is GAMES > Comments set to Chatty." },
            { "Language", "Mainframe > Settings > YOU > Language chooses the language she replies in. Changing it starts a fresh recent chat." },
            { "What should she call you?", "In Mainframe > Settings > YOU, enter a nickname under What should she call you? and press Save. Clear it or enter choom to go back to choom; Get to know me asks about your name, pronouns and interests and keeps the answers in me.md." },
            { "Get to know me", "Mainframe > Settings > YOU > Get to know me starts her questions about what to call you, your pronouns and what you're into. The answers go into me.md; say skip to pass a question or stop to end it." },
            { "Volume", "Mainframe > Settings > VOICE > Volume changes how loud her voice plays, from Mute to 150%. It changes Capri's voice, not the volume of other apps. With a cloud brain, talk louder or quieter works too." },
            { "Pitch", "Mainframe > Settings > VOICE > Pitch makes her voice lower or higher, from -6 to +6 semitones. It applies to every voice, including ElevenLabs, and she says a sample when you release the slider." },
            { "Speed", "Mainframe > Settings > VOICE > Speed changes how quickly she speaks, from 0.7x to 1.5x. It affects every voice and plays a sample when you release the slider. With a cloud brain, talk faster or slower works too." },
            { "Robot", "Mainframe > Settings > VOICE > Robot adds a robotic effect to her voice. HD and custom or cloud model voices keep their own amounts; the other voices share an amount." },
            { "Glitch", "Mainframe > Settings > VOICE > Glitch changes the glitch effect in her speech. HD and custom or cloud model voices keep their own amounts; this slider changes sound, not her startup animation." },
            { "Voice layers", "Mainframe > Settings > VOICE > Layers opens VOICE LAYERS, where Voice layers turns two quieter copies of her voice on or off. Layers are off by default. Each copy has its own Pitch and Delay, and the effect applies to every voice, including ElevenLabs. Hear her plays a sample and Defaults restores the layer settings." },
            { "Sounds", "Mainframe > Settings > VOICE > Sounds controls her sound effects, with Off and volume steps. Voice Volume has its own slider." },
            { "Typing sound", "Mainframe > Settings > VOICE > Typing sound turns the soft typing noise during her text replies on or off. Sounds in the same section controls the sound effects level." },
            { "Free voice in games", "Mainframe > Settings > VOICE > Free voice in games appears while HD voice is selected and is off by default. When on, a full-screen game or video makes the free voice take over from HD so the graphics card is freed for it." },
            { "Her voice in your mic", "Mainframe > Settings > VOICE > Her voice in your mic is off by default. Turned on, she plays your mic, the one picked under VOICE > Mic, and everything she says into a virtual mic, and you pick its other end as your mic in Discord or Roblox so friends hear you both: Steam Streaming Microphone when Steam's virtual mic is on the PC, or CABLE Output once VB-CABLE is installed. She uses VB-CABLE when both are there, and the note under the switch names the one to pick. If the line under it says to turn that mic on, Windows has it turned off in its sound settings. With neither, the switch stays off and Set up opens VB-Audio's own VB-CABLE setup from the copy she carries: Windows asks to let it run, you click Install Driver, then restart your PC. VB-CABLE is donationware from vb-cable.com; clicking that credit opens its page, where you can donate. Her voice still plays on your speakers, her sound effects stay out, and she never listens to that mic herself. Headphones stop your mic hearing her a second time." },
            { "Mini player", "Mainframe > Settings > MOVES > Mini player shows the song Windows reports, with playback controls and a place for her to sit. It hides during full-screen games and videos unless Mini player over full screen is on under HABITS; Spotify also gets a heart for liking the song." },
            { "Wander", "Mainframe > Settings > MOVES > Wander sets Off, Rarely, Sometimes, Often or Restless; right-click > Move > Wander also toggles it, and with a cloud brain so does stop wandering or wander more. She wanders while idle and you're active at the PC." },
            { "Sleep", "Mainframe > Settings > MOVES > Sleep chooses how long the PC is quiet before she dozes off, or Never. She sleeps until you're back. She also lies down awake for 2 to 4 minutes now and then, even on Never. Jobs, calls, voice chat, Gaming Mode and typing to her keep her awake. Moving the mouse wakes her own nap; a click, a pet, talking to her or asking for a job or call wakes an asked-for nap too. Asked to sleep during a job, she finishes it first; say stop to stop the job, or wake up to cancel the nap." },
            { "Pop-ins", "Mainframe > Settings > MOVES > Pop-ins sets Check in on me's pace: Rarely is 20 to 40 minutes, Sometimes 8 to 20, and Often 3 to 8. Check in on me under CAPRI turns the check-ins on or off." },
            { "Dance to music", "Mainframe > Settings > MOVES > Dance to music turns dancing with detected music on or off. Your music player needs to report what's playing; Move > Dance asks for a dance directly." },
            { "Glitch in at startup", "Mainframe > Settings > MOVES > Glitch in at startup switches her arrival effect on or off. It changes how she appears when Capri starts, not whether she starts with Windows." },
            { "KEYS >", "Mainframe > Settings > KEYS lets you click a binding, press new keys and click Confirm; Cancel keeps the old binding. The defaults are Ctrl + Alt + V for Talk, N for Mute mic, T for Type, H for Hide/show, P for Quiet and G for Gaming Mode. Push to talk starts unbound and can use a key or mouse button held while talking." },
            { "Push to talk: not set", "Mainframe > Settings > KEYS > Push to talk lets you hold a key or mouse button to talk to her, even with a game in front. It starts unbound. Click it, press the binding and click Confirm, or click Off to clear it. The binding still does its usual job in the game." },
            { "Quiet: Ctrl + Alt + P", "The default Ctrl + Alt + P toggles Quiet, and Mainframe > Settings > KEYS lets you change that key. It stops unsolicited glances, check-ins, cheers and jokes and pauses Hey Capri, while she still answers when you talk to her. Press it again to resume without changing Watch my screen or Check in on me." },
            { "Size", "Mainframe > Settings > CAPRI > Size changes Capri herself from Tiny to Giant. Right-click > Size also has size choices; Mainframe size is a separate setting for her window. With a cloud brain, make yourself bigger or smaller works too." },
            { "Mainframe size", "Mainframe > Settings > CAPRI > Mainframe size scales the window, with Auto or 100% to 200%. Auto keeps your screen's own scaling; Size changes Capri herself separately." },
            { "Mainframe colours", "Mainframe > Settings > CAPRI > Mainframe colours picks Night City, Black, White or Grey for the Mainframe and its windows. It changes straight away. Her bubble and her own colours stay as they are." },
            { "Check in on me", "Mainframe > Settings > CAPRI > Check in on me is the current name for Pop in on me. It enables her visits to say hi, attention check-ins, game and music cheers and the busy-PC joke; MOVES > Pop-ins changes the visit pace. With Wander off or a chosen seat she checks in from her spot instead of moving over." },
            { "Always on top", "Mainframe > Settings > CAPRI > Always on top keeps her above ordinary windows. An exclusive full-screen app can still cover her; borderless or windowed mode lets desktop overlays show." },
            { "Watch my screen", "Mainframe > Settings > WATCH > Watch my screen enables occasional comments, with Every setting the time between glances. Seeing requires a vision-capable brain: text-only models cannot take images. She skips unchanged or blank captures, Quiet pauses glances, and asking her to look is a separate action." },
            { "Remember what she sees", "Mainframe > Settings > WATCH > Remember what she sees works with Watch my screen. When she glances at your screen and says nothing, she still remembers what she saw for three hours, so you can ask about it. It has nothing to do with updating the app, and it uses a little more of your brain API." },
            { "Every", "Mainframe > Settings > WATCH > Every sets the gap between screen glances, from 10 seconds to 10 minutes. Watch my screen must be on; she can still skip a glance when the screen has not changed or she is busy." },
            { "Stay on my model", "Mainframe > Settings > BRAIN > Stay on my model keeps the selected NVIDIA model when it gets stuck. With it on she reports the problem instead of trying another model." },
            { "Replies", "Mainframe > Settings > BRAIN > Replies selects Short, Medium or Long answers. This changes the amount she says, while Bubble changes how long her text stays visible." },
            { "Max reply", "Mainframe > Settings > BRAIN > Max reply offers Auto, 256, 2K or 8K tokens for her longest reply. Auto keeps the usual reply budget and follows Replies above; the numbered choices allow that many tokens, with 2K meaning 2048 and 8K meaning 8192. Jobs keep extra room when they need it; choosing more room does not make every answer long." },
            { "Memory", "Mainframe > Settings > BRAIN > Memory chooses Short, Medium or Long for 8, 16 or 32 recent messages. That recent chat can survive restarts for up to a week; Remember our chats and me.md cover longer-term memories separately." },
            { "Memory size", "Mainframe > Settings > BRAIN > Memory size sets the context window in tokens for Ollama: Auto, 4K, 8K, 16K, 32K or 64K. Auto uses 4096 tokens with Short Memory and 8192 with Medium or Long Memory. It does not change a cloud brain or another local server's context size." },
            { "Bubble", "Mainframe > Settings > BRAIN > Bubble selects Quick, Normal or Long for how long her reply bubble stays up. The time also follows the reply's length; this does not change how much she says." },
            { "Custom model name", "Mainframe > Settings > BRAIN > Custom model name accepts an Ollama model you've already pulled, a model ID on your selected local server or one available to your brain key. Enter it and press Use; it does not install an arbitrary model for you." },
            { "Local server address", "LM Studio, Jan, KoboldCpp and llama.cpp can supply her NORMAL brain from this PC. Start the server with a model loaded, then choose NORMAL in Mainframe > BRAIN, press Refresh and pick its model. For a different address, use Mainframe > Settings > BRAIN > Local server address, enter an HTTP loopback address such as http://127.0.0.1:1234 and press Save. Refresh checks ports 1234, 1337, 5001 and 8080 plus your saved address." },
            { "Start with Windows", "Mainframe > Settings > HABITS > Start with Windows controls automatic launch for your Windows user. The installed copy enables it once on first run, and turning it off stays off after updates; Task Manager's Startup apps setting is reflected here too." },
            { "Start at login", "Mainframe > Settings > HABITS > Start at login opens Capri when you log in. It stays off until you turn it on." },
            { "Show on Discord", "Mainframe > Settings > HABITS > Show on Discord controls the Playing Capri activity while Discord is running on this PC. It shows a short activity and elapsed time, not song titles or the contents of jobs." },
            { "Use her cursor", "Mainframe > Settings > HABITS > Use her cursor lets YouTube searches and Spotify's volume slider use her visible pointer when a brain and the mouse permission are available. Spotify music uses play_music directly with either setting. Off uses the quick tools instead; it does not turn off explicit mouse and keyboard jobs." },
            { "Obsidian vault", "Pick a vault or Browse to a .md note to keep her notes there. Her own notes brings them back and keeps your vault copy." },
            { "Remember our chats", "Mainframe > Settings > HABITS > Remember our chats keeps daily transcripts and folds older chats into memories.md on this PC, with Open her memories opening their folder. Turning it off stops writing, folding, searching and reading these memories without deleting them. With a cloud brain, relevant recalled text and chats being folded go to that selected brain as context." },
            { "Perch", "Mainframe > Settings > HABITS > Perch selects the frames per second while she sits on a window. The sway takes the same time at each setting; above 30 fps she draws intermediate frames for smoother movement." },
            { "Keep PC awake for jobs", "Keeps the computer and screen awake while her job runs, she waits for your answer, or she reads your screen. Turn it off to let the computer sleep as usual." },
            { "Edit check-in lines", "Edit the bullet lines in check-ins.md to change what she says, or remove them to silence a check-in. It opens in your editor." },
            { "Comments", "Mainframe > Settings > GAMES > Comments selects Off, only when something happens, or Chatty. It runs on its own: Watch my screen and Check in on me being off don't stop it, so set it to Off for no game comments at all. Game commentary uses screen observations, sound levels and supported logs written by the game; it is separate from the timer under WATCH. With Live reactions on, her game lines show in their feed over the game instead of her bubble." },
            { "Live reactions", "Mainframe > Settings > GAMES > Live reactions is on by default, right under Comments. It runs while her game comments do: Comments on Events only or Chatty, or Gaming Mode on, which it is by default. When something happens in a full-screen game, like a kill, a death, a hit, a flash, a big sound, the screen changing or going dark, or a win or loss she can read on screen, her brain writes a short line that pops up on the right of the game's screen, a third of the way down, if it comes within about 2.5 seconds. A line that repeats one of her last ones is dropped, and with no brain or a slow one nothing shows. Up to four stack, newest at the bottom, and each fades after about 4 seconds. Her brain's look at what happened can follow, also within about 2.5 seconds. Each line sits on a dark plate in her Mainframe's look: quick lines read white beside a red bar, and her brain's look rose beside a cyan one. She says at most one out loud every 8 seconds, never over herself or you; Mute her and her Quiet key keep them as text, and so does ElevenLabs voice chat. The feed never takes clicks or focus and works over borderless full screen; exclusive full screen can't show it. Turned off, her game lines go back to her bubble." },
            { "Hide in full screen", "Mainframe > Settings > HABITS > Hide in full screen is off by default. When on, she hides while the foreground window fills its monitor and returns afterwards. A manual hide stays hidden. Speech and text follow her usual hidden behaviour. Gaming Mode takes priority while it is on." },
            { "Mini player over full screen", "Mainframe > Settings > HABITS > Mini player over full screen is off by default. When on, her enabled mini player can stay over borderless full-screen windows. Windows cannot show it over exclusive full screen. A manual hide and Gaming Mode still put the player away; Hide in full screen can hide her body while the player stays up." },
            { "Explore while I'm away", "Mainframe > Settings > HABITS > Explore while I'm away is off by default. After Explore after, five minutes by default, she moves only her own pointer and scrolls a browser or reader page under your mouse. She never clicks, types, opens or closes anything while exploring. Games, full-screen windows, password fields and blocked windows are excluded. Your mouse or keyboard input stops her; her own scrolling does not reset your away time. She stops after half an hour so your screen can turn off and your PC can sleep, and she never wakes a screen that has already gone off. With a brain that can see she sometimes makes one short comment using WATCH's pace." },
            { "Explore after", "Mainframe > Settings > HABITS > Explore after sets the idle time before Explore while I'm away starts: one, two, five, ten, fifteen or thirty minutes. Five minutes is the default. Her own scrolling does not count as you coming back." },
            { "Gaming Mode", "Say \"Hey Capri, activate gaming mode\" and she enters Gaming Mode. Mainframe > Settings > GAMES also has the Gaming Mode switch; the default key is Ctrl + Alt + G. It's on by default: a game in front brings it up with nothing said, and turning it off keeps it off until you turn it back on. She stays on your desktop as usual, you can still drag her, and she reacts when something happens in the game until it closes. Her HUD is switched off for now, so there's nothing to move. It works best on MAX INTELLIGENCE and is weaker on other brains. Settings > KEYS changes that key; press it again to turn the mode off, or ask turn off gaming mode. Gaming Mode does not by itself ask her to play. When she plays a game herself as a job, she goes into Gaming Mode by herself once the game is in front; it stays up until the game closes, and turning it off keeps it off for that job." },
            { "Clip my games", "Mainframe > Settings > CLIPS > Clip my games is off by default. When on, it keeps up to the last two minutes of a detected game's video and PC playback sound in memory while the game is in front. Say clip that or scroll that BD to use your default length, or name a length such as clip the last two minutes. CLIPS has a save-folder picker, default length from 15 seconds to 2 minutes, target frame rate from 15 to 60 fps, maximum resolution Auto/480p/720p/1080p and video bitrate Auto/2/4/8/12/20Mbps. Clips are MP4 files in your chosen folder, Videos\\Capri Clips by default. Folder changes affect future clips and do not move old files. FPS may drop under load or the 240 MB memory budget, especially in longer clips; Auto resolution may lower detail to stay smooth. Matching repeated requests within 8 seconds share one save and one notification. Each save chimes and pops up CLIP SAVED at the top right of the game's screen; click it to see the clip. Open clips folder in Settings > CLIPS opens them all." },
            { "Save big moments", "Mainframe > Settings > CLIPS > Save big moments is directly under Clip my games and off by default. Turning it on also turns Clip my games on; turning Clip my games off turns both off. With both on, her game commentary decides whether a moment is worth keeping and saves your chosen default length of buffered video and PC sound. Comments must be running: Gaming Mode runs them, but with Comments off outside Gaming Mode she judges and saves nothing automatically. She reacts as usual, then saves it with no spoken notice; failures stay in her log. Moments under 30 seconds apart do not extend a clip or save another. Clips go to your chosen CLIPS folder (Videos\\Capri Clips by default) like any other clip and take up space the same way; there is no limit on how many she saves and she does not delete old clips." },
            { "Default length", "Mainframe > Settings > CLIPS > Default length chooses 15, 30, 45, 60, 90 or 120 seconds for clip that and Save big moments. The default is 30 seconds. An explicit request such as clip the last two minutes overrides it, using only video already buffered." },
            { "Frame rate", "Mainframe > Settings > CLIPS > Frame rate targets 15, 24, 30 or 60 fps for future capture. 30 fps is the default. Slow capture or the 240 MB rolling memory budget can reduce the actual rate, especially for longer clips. It does not invent extra frames or change playback speed." },
            { "Resolution", "Mainframe > Settings > CLIPS > Resolution chooses Auto or up to 480p, 720p or 1080p, preserving the game's shape without upscaling. Auto starts at up to 1080p and can lower it to stay smooth. New capture uses the chosen maximum; it cannot restore detail missing from older buffered frames." },
            { "Video bitrate", "Mainframe > Settings > CLIPS > Video bitrate chooses Auto or an H.264 average target of 2, 4, 8, 12 or 20 Mbps for future saves. Higher values make larger files. Auto uses the picture size, up to 12 Mbps; bitrate is not a guaranteed file-size or peak limit." },
            { "Save folder", "Mainframe > Settings > CLIPS > Choose folder picks an existing folder for future MP4s. Videos\\Capri Clips is the default. Existing clips stay where they were. Open clips folder opens the selected folder; clicking a CLIP SAVED popup reveals that particular file, including an older clip in its original folder." },
            { "Mute her", "Mainframe > Settings > GAMES > Mute her stops her talking on her own, and she still answers when you talk to her." },
            { "Fast hands in games", "Mainframe > Settings > GAMES > Fast hands in games is on by default. On a Claude key, a job that plays a game runs on Claude Haiku 5.5, because a game doesn't wait: turns take about 3 seconds instead of 10 or more and cost a fraction. When she's stuck she asks the brain you picked what to do, or Claude Sonnet 5.5 if you picked Haiku, which costs a few cents a time. Chat stays on the brain you picked. Turn it off to play on your picked brain. Other brains aren't changed by it." },
            { "Hide Capri", "Mainframe > CAPRI > Hide Capri hides her and stops her moving, chat and speech. The button changes to Show Capri to bring her back. Hiding her keeps Capri running." },
            { "Bring here", "Mainframe > CAPRI > Bring here wakes her and brings her to the screen your mouse is on." },
            { "Ride cursor", "Mainframe > CAPRI > Ride cursor makes her follow your mouse smoothly on its monitor. Mouse clicks pass through her while she rides. The button becomes Hop off; stopping the ride returns her to her previous position." },
            { "Open her notes", "Mainframe > Settings > YOU > Open her notes opens me.md in your text editor. Tell her remember or forget a fact, or edit the file and save it; she reads these notes when you chat. Get to know me writes your nickname, pronouns and interests there too." },
            { "Edit personality.md", "Mainframe > Settings > YOU > Her personality > Edit personality.md opens personality.md in your text editor, starting from her default. Rewrite how she acts and talks, save, and her next reply uses it. Her safety lines stay in her code and always come after it, so it can't change them. Reset to her default puts her back and keeps yours as personality.backup.md. On Mac and Linux it's under Settings in her right-click menu." },
            { "Check for updates", "Mainframe > CAPRI > Check for updates checks for a newer version. She also checks after startup. When there is one, Get Capri shows in her right-click menu and opens its download page. Settings and notes stay in her data folder across updates." },
            { "SECURITY >", "Mainframe > Settings > HABITS > Security opens SECURITY: Lockdown turns every toggle off, Guarded turns the first three on, and Trusted, the default, turns the first seven on. Blackwall turns all eleven on, including passwords and Listen for Hey Capri; a different mix shows Custom, and choosing a preset resets its toggles. With an action toggle off she asks first, except passwords and card numbers are yours to type and Hey Capri simply stops listening." },
        };
        internal static void Explain(Control control, string name)
        {
            if (name == "Brain API key") name = "NVIDIA, Google AI Studio (Gemini) or OpenRouter API key";
            else if (name == "Layers") name = "Voice layers";
            else if (name == "Set up") name = "CUSTOM LOCAL";
            else if (name == "Her personality") name = "Edit personality.md";
            else if (name == "Speech model") name = "Default model";
            string text;
            if (!Text.TryGetValue(name, out text)) return;
            text = Brief(text);
            ToolTip.SetTip(control, new TextBlock { Text = text, MaxWidth = 332, TextWrapping = Avalonia.Media.TextWrapping.Wrap, FontFamily = MainframeTheme.Text, FontSize = MainframeTheme.Size, Foreground = MainframeTheme.White });
            ToolTip.SetShowDelay(control, 400);
        }
        internal static string Brief(string facts)
        {
            string text = Regex.Replace(facts ?? "", @"^Mainframe(?: > (?:Settings|Simple Settings|Advanced Settings|[A-Z][A-Z &-]+))* > ", "");
            if (text.Length > 0) text = char.ToUpperInvariant(text[0]) + text.Substring(1);
            double height = MainframeTheme.Words("Ag").Height * 6;
            if (Height(text) <= height) return text;
            const string more = " Ask Capri for more";
            string kept = "";
            foreach (Match sentence in Regex.Matches(text, @".+?(?:[.!?](?=\s+[A-Z]|$)|$)"))
            {
                string next = text.Substring(0, sentence.Index + sentence.Length).Trim();
                if (Height(next + more) > height) break;
                kept = next;
            }
            if (kept.Length == 0)
            {
                foreach (Match word in Regex.Matches(text, @"\S+"))
                {
                    string next = text.Substring(0, word.Index + word.Length).TrimEnd();
                    if (Height(next + "..." + more) > height) break;
                    kept = next;
                }
                if (kept.Length > 0) kept += "...";
            }
            return kept.Length > 0 ? kept + more : more.TrimStart();
        }
        private static double Height(string text) { var words = MainframeTheme.Words(text); words.MaxTextWidth = 332; return words.Height; }
    }
}
